-- ============================================
-- NimbusAI Core Database (PostgreSQL)
-- Generated for Data Analyst Intern Assignment
-- ============================================

DROP SCHEMA IF EXISTS nimbus CASCADE;
CREATE SCHEMA nimbus;
SET search_path TO nimbus;

-- Subscription Plans
CREATE TABLE plans (
    plan_id SERIAL PRIMARY KEY,
    plan_name VARCHAR(50) NOT NULL,
    plan_tier VARCHAR(20) NOT NULL,  -- free, starter, professional, enterprise
    monthly_price_usd DECIMAL(10,2),
    annual_price_usd DECIMAL(10,2),
    max_users INT,
    max_projects INT,
    storage_gb INT,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP DEFAULT NOW()
);


-- Customer Accounts
CREATE TABLE customers (
    customer_id SERIAL PRIMARY KEY,
    company_name VARCHAR(200) NOT NULL,
    industry VARCHAR(100),
    company_size VARCHAR(20),  -- small, medium, large, enterprise
    country_code CHAR(2),
    country_name VARCHAR(100),
    timezone VARCHAR(50),
    contact_email VARCHAR(255),
    contact_name VARCHAR(200),
    signup_date DATE NOT NULL,
    signup_source VARCHAR(50),  -- organic, referral, paid_ads, partner, event
    is_active BOOLEAN DEFAULT TRUE,
    churned_at TIMESTAMP,
    churn_reason VARCHAR(200),
    nps_score INT,  -- 0-10, some NULL
    created_at TIMESTAMP DEFAULT NOW(),
    updated_at TIMESTAMP DEFAULT NOW()
);


-- Team Members (users within customer accounts)
CREATE TABLE team_members (
    member_id SERIAL PRIMARY KEY,
    customer_id INT REFERENCES customers(customer_id),
    email VARCHAR(255),
    full_name VARCHAR(200),
    role VARCHAR(50),  -- admin, manager, member, viewer, billing
    is_active BOOLEAN DEFAULT TRUE,
    invited_at TIMESTAMP,
    joined_at TIMESTAMP,
    last_login_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT NOW()
);

;

-- Subscription History (includes plan changes)
CREATE TABLE subscriptions (
    subscription_id SERIAL PRIMARY KEY,
    customer_id INT REFERENCES customers(customer_id),
    plan_id INT REFERENCES plans(plan_id),
    status VARCHAR(20),  -- active, cancelled, paused, trial, expired
    billing_cycle VARCHAR(20),  -- monthly, annual
    start_date DATE NOT NULL,
    end_date DATE,
    mrr_usd DECIMAL(10,2),  -- monthly recurring revenue
    discount_pct DECIMAL(5,2) DEFAULT 0,
    trial_end_date DATE,
    cancellation_reason VARCHAR(200),
    created_at TIMESTAMP DEFAULT NOW()
);


-- Billing Invoices
CREATE TABLE billing_invoices (
    invoice_id SERIAL PRIMARY KEY,
    customer_id INT REFERENCES customers(customer_id),
    subscription_id INT REFERENCES subscriptions(subscription_id),
    invoice_date DATE NOT NULL,
    due_date DATE,
    amount_usd DECIMAL(10,2),
    tax_usd DECIMAL(10,2) DEFAULT 0,
    total_usd DECIMAL(10,2),
    status VARCHAR(20),  -- paid, pending, overdue, refunded, void
    payment_method VARCHAR(30),  -- credit_card, bank_transfer, paypal, wire
    currency VARCHAR(3) DEFAULT 'USD',  -- some inconsistencies here
    paid_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT NOW()
);


-- Support Tickets
CREATE TABLE support_tickets (
    ticket_id SERIAL PRIMARY KEY,
    customer_id INT REFERENCES customers(customer_id),
    member_id INT REFERENCES team_members(member_id),
    category VARCHAR(50),
    priority VARCHAR(20),
    status VARCHAR(30),
    subject VARCHAR(500),
    created_at TIMESTAMP NOT NULL,
    first_response_at TIMESTAMP,
    resolved_at TIMESTAMP,
    satisfaction_score INT,  -- 1-5, some NULL
    escalated BOOLEAN DEFAULT FALSE,
    tags VARCHAR(200)  -- comma-separated, messy
);


-- Feature Flags (which features are enabled per plan)
CREATE TABLE feature_flags (
    flag_id SERIAL PRIMARY KEY,
    plan_id INT REFERENCES plans(plan_id),
    feature_key VARCHAR(100) NOT NULL,
    feature_name VARCHAR(200),
    is_enabled BOOLEAN DEFAULT FALSE,
    enabled_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT NOW()
);


-- Indexes for common queries
CREATE INDEX idx_customers_signup ON customers(signup_date);
CREATE INDEX idx_customers_active ON customers(is_active);
CREATE INDEX idx_subscriptions_customer ON subscriptions(customer_id);
CREATE INDEX idx_subscriptions_status ON subscriptions(status);
CREATE INDEX idx_invoices_customer ON billing_invoices(customer_id);
CREATE INDEX idx_invoices_date ON billing_invoices(invoice_date);
CREATE INDEX idx_tickets_customer ON support_tickets(customer_id);
CREATE INDEX idx_tickets_created ON support_tickets(created_at);
CREATE INDEX idx_members_customer ON team_members(customer_id);
CREATE INDEX idx_feature_flags_plan ON feature_flags(plan_id);

